(()=>{document.addEventListener("DOMContentLoaded",function(){var t=document.querySelector("[data-native-share]");if(t){var r=t.dataset.shareUrl||window.location.href,n=t.dataset.shareTitle||document.title,o=t.dataset.shareText||"",e=t.getAttribute("aria-label")||"",i=t.dataset.copiedLabel||e;t.addEventListener("click",async function(){try{if(navigator.share){await navigator.share({title:n,text:o,url:r});return}navigator.clipboard&&navigator.clipboard.writeText&&(await navigator.clipboard.writeText(r),t.setAttribute("aria-label",i),t.setAttribute("title",i),window.setTimeout(function(){t.setAttribute("aria-label",e),t.setAttribute("title",e)},1800))}catch(a){if(a&&a.name==="AbortError")return;console.warn("Share failed",a)}})}});})();
